"""Adjust the platform folders generated by `flutter create` (CI runs this).

    flutter create --platforms=android,windows --org com.eldawly --project-name wiring_academy .
    python tool/patch_platforms.py

Android: Arabic app label, launcher icons, portrait + landscape.
Windows: window title/size and app icon.
"""
import pathlib
import re
import shutil

APP = pathlib.Path(__file__).resolve().parent.parent
ICON = APP / "tool" / "icon"
LABEL = "أكاديمية التمديدات"


def patch_android() -> None:
    man = APP / "android/app/src/main/AndroidManifest.xml"
    if not man.exists():
        return
    s = man.read_text(encoding="utf-8")
    s = re.sub(r'android:label="[^"]*"', f'android:label="{LABEL}"', s, count=1)
    man.write_text(s, encoding="utf-8")
    res = APP / "android/app/src/main/res"
    for folder, size in (("mdpi", 48), ("hdpi", 72), ("xhdpi", 96), ("xxhdpi", 144), ("xxxhdpi", 192)):
        d = res / f"mipmap-{folder}"
        if d.exists():
            shutil.copy2(ICON / f"ic_{size}.png", d / "ic_launcher.png")
    print("android patched")


def patch_windows() -> None:
    main_cpp = APP / "windows/runner/main.cpp"
    if not main_cpp.exists():
        return
    s = main_cpp.read_text(encoding="utf-8")
    s = re.sub(r'window\.Create\(L"[^"]*"', 'window.Create(L"Wiring Academy"', s)
    s = re.sub(r"Win32Window::Size size\(\d+, \d+\)", "Win32Window::Size size(1366, 820)", s)
    main_cpp.write_text(s, encoding="utf-8")
    ico = APP / "windows/runner/resources/app_icon.ico"
    if ico.parent.exists():
        shutil.copy2(ICON / "app_icon.ico", ico)
    print("windows patched")


if __name__ == "__main__":
    patch_android()
    patch_windows()
